<?php require_once __DIR__.'/_bootstrap.php';if($_SERVER['REQUEST_METHOD']!=='POST')apiError('Method not allowed');verifyCsrf();$tableId=filter_var(postField('table_id'),FILTER_VALIDATE_INT);$frames=max(0,(int)postField('frames_played',0));$points=max(0,(int)postField('points_used',0));$payment=in_array(postField('payment_method'),['cash','jazzcash','easypaisa','ledger','mixed'],true)?postField('payment_method'):'cash';if(!$tableId)apiError('Invalid table.');$db=getDB();try{$db->beginTransaction();$q=$db->prepare("SELECT s.*,rp.rate_per_minute,rp.rate_per_frame,rp.slab_config,p.name player_name,p.tier,p.loyalty_points,p.member_rate_override,c.loyalty_points_rate,c.loyalty_redemption_rate FROM sessions s JOIN tables t ON t.id=s.table_id JOIN clubs c ON c.id=s.club_id LEFT JOIN rate_plans rp ON rp.id=s.rate_plan_id LEFT JOIN players p ON p.id=s.player_id WHERE s.table_id=? AND s.club_id=? AND s.status IN ('running','paused') FOR UPDATE");$q->execute([$tableId,$_SESSION['club_id']]);$s=$q->fetch();if(!$s)throw new RuntimeException('No billable session was found.');$pause=(int)$s['total_pause_seconds'];if($s['status']==='paused'&&$s['pause_start'])$pause+=max(0,time()-strtotime($s['pause_start']));$minutes=max(0,(time()-strtotime($s['start_time'])-$pause)/60);switch($s['billing_type']){case'per_frame':$tableAmount=$frames*(float)$s['rate_per_frame'];break;case'slab':$tableAmount=calculateSlabBilling($minutes,$s['slab_config']);break;case'challenge':$tableAmount=(float)$s['challenge_amount'];break;default:$tableAmount=$minutes*(float)$s['rate_per_minute'];}$cafeQ=$db->prepare("SELECT COALESCE(SUM(total_amount),0) FROM cafe_orders WHERE session_id=? AND status IN ('open','completed')");$cafeQ->execute([$s['id']]);$cafe=(float)$cafeQ->fetchColumn();$discount=$tableAmount*(max(tierDiscount($s['tier']??'regular'),(float)($s['member_rate_override']??0))/100);$availablePoints=(int)($s['loyalty_points']??0);$points=min($points,$availablePoints);$pointDiscount=$points*(float)$s['loyalty_redemption_rate'];$total=max(0,$tableAmount+$cafe-$discount-$pointDiscount);$earned=(int)floor($total/max(1,(float)$s['loyalty_points_rate']));$db->prepare("UPDATE sessions SET end_time=NOW(),pause_start=NULL,total_pause_seconds=?,frames_played=?,table_amount=?,cafe_amount=?,discount_amount=?,points_used=?,points_earned=?,total_amount=?,payment_method=?,status='completed' WHERE id=?")->execute([$pause,$frames,$tableAmount,$cafe,$discount+$pointDiscount,$points,$earned,$total,$payment,$s['id']]);$db->prepare("UPDATE cafe_orders SET status='completed',payment_method=? WHERE session_id=? AND status='open'")->execute([$payment,$s['id']]);$db->prepare("UPDATE tables SET status='available' WHERE id=?")->execute([$tableId]);if($s['player_id']){$newPoints=$availablePoints-$points+$earned;$tier=$newPoints>=5000?'platinum':($newPoints>=1500?'gold':($newPoints>=500?'silver':'regular'));$db->prepare('UPDATE players SET loyalty_points=?,total_spent=total_spent+?,total_visits=total_visits+1,last_visit=NOW(),tier=? WHERE id=?')->execute([$newPoints,$total,$tier,$s['player_id']]);$db->prepare('INSERT INTO player_loyalty_log (player_id,session_id,points_change,reason,balance_after,created_by) VALUES (?,?,?,?,?,?)')->execute([$s['player_id'],$s['id'],$earned-$points,'Session payment',$newPoints,$_SESSION['user_id']]);if($tier!==($s['tier']??'regular'))$db->prepare("INSERT INTO notifications(club_id,type,message) VALUES(?,?,?)")->execute([$_SESSION['club_id'],'tier',''.($s['player_name']??'Player').' upgraded to '.ucfirst($tier).' tier!']);}if($shift=activeShiftId())$db->prepare('UPDATE shifts SET total_revenue=total_revenue+?,total_transactions=total_transactions+1 WHERE id=?')->execute([$total,$shift]);$db->commit();audit('session_completed','sessions',(int)$s['id'],null,['total'=>$total]);jsonResponse(true,'Payment confirmed. '.money($total).' collected.', ['total'=>$total,'session_id'=>$s['id']]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();apiError($e->getMessage());}
